import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import API from '../services/api';

const fileIcon = (type) => ({ '.pdf': '📕', '.docx': '📘', '.xlsx': '📗', '.jpg': '🖼', '.jpeg': '🖼' }[type] || '📄');

export default function Documents() {
  const { user } = useAuth();
  const [docs, setDocs] = useState([]);
  const [categories, setCategories] = useState([]);
  const [filters, setFilters] = useState({ search: '', category: '', department: '', startDate: '', endDate: '' });
  const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });
  const [selected, setSelected] = useState(null);
  const [versionFile, setVersionFile] = useState(null);
  const [versionNotes, setVersionNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState({ text: '', type: '' });

  const canManage = ['Admin', 'Record Manager'].includes(user.role);

  const fetchDocs = useCallback(async (page = 1) => {
    setLoading(true);
    try {
      const params = { page, limit: 10, ...Object.fromEntries(Object.entries(filters).filter(([, v]) => v)) };
      const { data } = await API.get('/documents', { params });
      setDocs(data.docs);
      setPagination({ page: data.page, pages: data.pages, total: data.total });
    } catch {}
    setLoading(false);
  }, [filters]);

  useEffect(() => { API.get('/categories').then(r => setCategories(r.data)).catch(() => {}); }, []);
  useEffect(() => { fetchDocs(1); }, [fetchDocs]);

  const showMsg = (text, type = 'info') => { setMsg({ text, type }); setTimeout(() => setMsg({ text: '', type: '' }), 3000); };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this document?')) return;
    try { await API.delete(`/documents/${id}`); showMsg('Document deleted', 'success'); fetchDocs(pagination.page); }
    catch (err) { showMsg(err.response?.data?.message || 'Delete failed', 'error'); }
  };

  const handleDownload = async (doc) => {
    try {
      const res = await API.get(`/documents/${doc._id}/download`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a'); a.href = url; a.download = doc.originalName || doc.title; a.click();
      window.URL.revokeObjectURL(url);
    } catch { showMsg('Download failed', 'error'); }
  };

  const handleNewVersion = async (docId) => {
    if (!versionFile) return showMsg('Select a file', 'error');
    const fd = new FormData(); fd.append('file', versionFile); fd.append('notes', versionNotes);
    try {
      await API.post(`/documents/${docId}/version`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      showMsg('New version uploaded!', 'success');
      setVersionFile(null); setVersionNotes('');
      const { data } = await API.get(`/documents/${docId}`); setSelected(data);
      fetchDocs(pagination.page);
    } catch (err) { showMsg(err.response?.data?.message || 'Failed', 'error'); }
  };

  const handleRestore = async (docId, versionNumber) => {
    try {
      await API.put(`/documents/${docId}/restore`, { versionNumber });
      showMsg(`Restored to v${versionNumber}`, 'success');
      const { data } = await API.get(`/documents/${docId}`); setSelected(data);
    } catch { showMsg('Restore failed', 'error'); }
  };

  const msgColors = { success: { bg: '#f0fdf4', border: '#bbf7d0', color: '#166534' }, error: { bg: '#fef2f2', border: '#fecaca', color: '#dc2626' }, info: { bg: '#eff6ff', border: '#bfdbfe', color: '#1d4ed8' } };

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>Documents</h1>
          <p style={styles.sub}>Manage and retrieve your organization's records</p>
        </div>
        <span style={styles.totalBadge}>{pagination.total} total</span>
      </div>

      {msg.text && <div style={{ ...styles.msgBox, ...msgColors[msg.type] }}>{msg.text}</div>}

      {/* Filters */}
      <div style={styles.filterCard}>
        <div style={styles.filterGrid}>
          <div style={styles.searchWrap}>
            <span style={styles.searchIcon}>🔍</span>
            <input style={styles.searchInput} placeholder="Search documents..." value={filters.search}
              onChange={e => setFilters({ ...filters, search: e.target.value })} />
          </div>
          <select style={styles.select} value={filters.category} onChange={e => setFilters({ ...filters, category: e.target.value })}>
            <option value="">All Categories</option>
            {categories.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
          </select>
          <input style={styles.select} placeholder="Department" value={filters.department}
            onChange={e => setFilters({ ...filters, department: e.target.value })} />
          <input style={styles.select} type="date" value={filters.startDate} onChange={e => setFilters({ ...filters, startDate: e.target.value })} />
          <input style={styles.select} type="date" value={filters.endDate} onChange={e => setFilters({ ...filters, endDate: e.target.value })} />
          <button style={styles.clearBtn} onClick={() => setFilters({ search: '', category: '', department: '', startDate: '', endDate: '' })}>✕ Clear</button>
        </div>
      </div>

      {/* Table */}
      <div style={styles.tableCard}>
        {loading ? (
          <div style={styles.loading}>⏳ Loading documents...</div>
        ) : docs.length === 0 ? (
          <div style={styles.empty}><span style={{ fontSize: '40px' }}>📭</span><p>No documents found</p></div>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr style={styles.thead}>
                <th style={styles.th}>Document</th>
                <th style={styles.th}>Category</th>
                <th style={styles.th}>Department</th>
                <th style={styles.th}>Version</th>
                <th style={styles.th}>Uploaded By</th>
                <th style={styles.th}>Date</th>
                <th style={styles.th}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {docs.map((doc, i) => (
                <tr key={doc._id} style={{ ...styles.tr, background: i % 2 === 0 ? '#fff' : '#fafafa' }}>
                  <td style={styles.td}>
                    <div style={styles.docCell}>
                      <span style={styles.fileIcon}>{fileIcon(doc.fileType)}</span>
                      <div>
                        <p style={styles.docTitle}>{doc.title}</p>
                        <p style={styles.docSize}>{(doc.fileSize / 1024).toFixed(1)} KB • {doc.fileType?.replace('.', '').toUpperCase()}</p>
                      </div>
                    </div>
                  </td>
                  <td style={styles.td}><span style={styles.catBadge}>{doc.category?.name || '—'}</span></td>
                  <td style={styles.td}>{doc.department}</td>
                  <td style={styles.td}><span style={styles.versionBadge}>v{doc.currentVersion}</span></td>
                  <td style={styles.td}>{doc.uploadedBy?.name || '—'}</td>
                  <td style={styles.td}>{new Date(doc.createdAt).toLocaleDateString()}</td>
                  <td style={styles.td}>
                    <div style={styles.actions}>
                      <button style={styles.btn('#4f46e5')} onClick={() => handleDownload(doc)}>⬇</button>
                      <button style={styles.btn('#0891b2')} onClick={async () => { const { data } = await API.get(`/documents/${doc._id}`); setSelected(data); }}>👁</button>
                      {canManage && <button style={styles.btn('#ef4444')} onClick={() => handleDelete(doc._id)}>🗑</button>}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Pagination */}
      {pagination.pages > 1 && (
        <div style={styles.pagination}>
          <button style={styles.pageBtn} onClick={() => fetchDocs(pagination.page - 1)} disabled={pagination.page === 1}>← Prev</button>
          {Array.from({ length: pagination.pages }, (_, i) => i + 1).map(p => (
            <button key={p} style={{ ...styles.pageBtn, ...(p === pagination.page ? styles.activePage : {}) }} onClick={() => fetchDocs(p)}>{p}</button>
          ))}
          <button style={styles.pageBtn} onClick={() => fetchDocs(pagination.page + 1)} disabled={pagination.page === pagination.pages}>Next →</button>
        </div>
      )}

      {/* Detail Modal */}
      {selected && (
        <div style={styles.overlay} onClick={() => setSelected(null)}>
          <div style={styles.modal} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <div style={styles.modalTitle}>
                <span style={{ fontSize: '28px' }}>{fileIcon(selected.fileType)}</span>
                <div>
                  <h3 style={{ color: '#1e293b', fontSize: '18px' }}>{selected.title}</h3>
                  <p style={{ color: '#64748b', fontSize: '13px' }}>{selected.department} • {selected.originalName}</p>
                </div>
              </div>
              <button style={styles.closeBtn} onClick={() => setSelected(null)}>✕</button>
            </div>

            <div style={styles.modalMeta}>
              {[
                { label: 'Category', value: selected.category?.name || '—' },
                { label: 'File Size', value: `${(selected.fileSize / 1024).toFixed(1)} KB` },
                { label: 'Current Version', value: `v${selected.currentVersion}` },
                { label: 'Tags', value: selected.tags?.join(', ') || 'None' },
              ].map(m => (
                <div key={m.label} style={styles.metaItem}>
                  <span style={styles.metaLabel}>{m.label}</span>
                  <span style={styles.metaValue}>{m.value}</span>
                </div>
              ))}
            </div>

            <h4 style={styles.modalSectionTitle}>Version History</h4>
            <div style={styles.versionList}>
              {selected.versions?.map(v => (
                <div key={v.versionNumber} style={{ ...styles.versionItem, ...(v.versionNumber === selected.currentVersion ? styles.currentVersion : {}) }}>
                  <div style={styles.versionBadgeModal}>v{v.versionNumber}</div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontSize: '13px', fontWeight: '500' }}>{v.notes || 'No notes'}</p>
                    <p style={{ fontSize: '11px', color: '#94a3b8' }}>{new Date(v.uploadedAt).toLocaleString()}</p>
                  </div>
                  {v.versionNumber === selected.currentVersion && <span style={styles.currentTag}>Current</span>}
                  {canManage && v.versionNumber !== selected.currentVersion && (
                    <button style={styles.restoreBtn} onClick={() => handleRestore(selected._id, v.versionNumber)}>Restore</button>
                  )}
                </div>
              ))}
            </div>

            {canManage && (
              <div style={styles.newVersionBox}>
                <h4 style={styles.modalSectionTitle}>Upload New Version</h4>
                <input type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg" onChange={e => setVersionFile(e.target.files[0])} style={{ marginBottom: '10px', fontSize: '13px' }} />
                <input style={styles.versionInput} placeholder="Version notes (optional)" value={versionNotes} onChange={e => setVersionNotes(e.target.value)} />
                <button style={styles.uploadVersionBtn} onClick={() => handleNewVersion(selected._id)}>⬆ Upload New Version</button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: { padding: '28px', maxWidth: '1200px', margin: '0 auto' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '24px' },
